select:
select a.id AS id, a.order_detail_id AS orderDetailId, a.solution_type AS solutionType, a.solution_role AS solutionRole, b.product_name AS productName, b.order_no AS orderNo, a.return_num AS returnNum, a.exchange_num AS exchangeNum, a.rework_num AS reworkNum, a.discounts_amount AS discountsAmount, a.claimant_amount AS claimantAmount, a.undo_reason AS undoReason, DATE_FORMAT(a.created_time, '%Y-%m-%d %H:%i:%s') AS createdTime, DATE_FORMAT(a.update_time, '%Y-%m-%d %H:%i:%s') AS updateTime, cs.`name` AS createdStaffName, us.`name` AS updateStaffName, a.judge AS judge, a.judge_desc AS judgeDesc, a.problem_type AS problemType from jml_case_solution a left join jml_staff cs on a.created_staff_id = cs.id left join jml_staff us ON a.update_staff_id = us.id left join jml_case_order_detail b on a.order_detail_id = b.id
and a.case_id = #{caseId}
and a.solution_role = #{solutionRole}
order by a.created_time desc
